516:   $('#gamePortrait').innerHTML = renderPortrait(state.god, { age });
517:   $('#cardName').textContent = state.god.name;
518:   $('#cardSub').textContent = `${rankName(rank)} · ${domainName(d)} · ${ageLabel(age)}`;
519:   $('#cardMight').textContent = fmt(might);
520:   const next = RANKS[state.rank + 1];
521:   const curNeed = rank.need;
522:   const pct = next ? Math.max(0, Math.min(100, ((might - curNeed) / (next.need - curNeed)) * 100)) : 100;
523:   $('#mightBar').style.width = pct + '%';
524:   if (next && might < next.need) {
525:     $('#mightNext').textContent = t('{n} more might to become {name}', { n: fmt(next.need - might), name: rankName(next) });
526:   } else if (next) {
