528:   } else {
529:     $('#mightNext').textContent = t('You stand at the summit of the divine order.');
530:   }
531:   $('#cardFollowers').textContent = fmt(state.followers);
532:   const delta = state.followerDelta || 0;
533:   $('#followersTrend').textContent = delta > 0 ? `+${fmt(delta)}` : delta < 0 ? `${fmt(delta)}` : '';
534:   $('#followersTrend').className = 'trend' + (delta < 0 ? ' down' : '');
